import { expectLogic } from 'kea-test-utils'

import { dayjs } from 'lib/dayjs'

import { initKeaTests } from '~/test/init'

import {
    hogFlowsBatchJobsList,
    hogFlowsPartialUpdate,
    hogFlowsRetrieve,
    hogFlowsSchedulesCreate,
    hogFlowsSchedulesDestroy,
    hogFlowsSchedulesList,
    hogFlowsUserBlastRadiusCreate,
} from 'products/workflows/frontend/generated/api'
import type {
    HogFlowApi,
    HogFlowBatchJobApi,
    HogFlowScheduleApi,
} from 'products/workflows/frontend/generated/api.schemas'

import { broadcastWizardLogic } from './broadcastWizardLogic'
import { ONE_TIME_RRULE } from '../Workflows/hogflows/steps/components/rrule-helpers'

jest.mock('products/workflows/frontend/generated/api', () => ({
    ...jest.requireActual('products/workflows/frontend/generated/api'),
    hogFlowsBatchJobsList: jest.fn(),
    hogFlowsPartialUpdate: jest.fn(),
    hogFlowsRetrieve: jest.fn(),
    hogFlowsSchedulesCreate: jest.fn(),
    hogFlowsSchedulesDestroy: jest.fn(),
    hogFlowsSchedulesList: jest.fn(),
    hogFlowsUserBlastRadiusCreate: jest.fn(),
}))

const schedule = (id: string, status: string): HogFlowScheduleApi =>
    ({
        id,
        status,
        rrule: ONE_TIME_RRULE,
        starts_at: dayjs().add(1, 'day').toISOString(),
        timezone: 'UTC',
    }) as unknown as HogFlowScheduleApi

const broadcastFixture = (status: string, schedules: HogFlowScheduleApi[]): HogFlowApi =>
    ({
        id: 'broadcast-1',
        name: 'Launch news',
        status,
        origin_product: 'broadcasts',
        schedules,
        actions: [
            { id: 'trigger_node', type: 'trigger', config: { type: 'batch', filters: { properties: [] } } },
            {
                id: 'email_node',
                type: 'function_email',
                config: {
                    inputs: {
                        email: { value: { from: { integrationId: 1 }, subject: 'Hello', html: '<p>Hi</p>' } },
                    },
                },
            },
        ],
    }) as unknown as HogFlowApi

describe('broadcastWizardLogic', () => {
    let logic: ReturnType<typeof broadcastWizardLogic.build>

    async function mountWith(broadcast: HogFlowApi, batchJobs: HogFlowBatchJobApi[] = []): Promise<void> {
        jest.mocked(hogFlowsRetrieve).mockResolvedValue(broadcast)
        jest.mocked(hogFlowsBatchJobsList).mockResolvedValue(batchJobs)
        jest.mocked(hogFlowsPartialUpdate).mockImplementation(
            async (_projectId, _id, body) => ({ ...broadcast, status: (body as any)?.status ?? 'draft' }) as HogFlowApi
        )
        logic = broadcastWizardLogic({ id: broadcast.id })
        logic.mount()
        await expectLogic(logic).toFinishAllListeners()
    }

    beforeEach(() => {
        jest.clearAllMocks()
        initKeaTests()
        jest.mocked(hogFlowsUserBlastRadiusCreate).mockResolvedValue({
            affected: 10,
            total: 100,
            limit: 1000,
            dedupe_key: 'email',
            confirm_token: 'token',
        })
    })

    afterEach(() => {
        logic?.unmount()
    })

    it('replaces a paused schedule with a fresh one when relaunching', async () => {
        await mountWith(broadcastFixture('draft', [schedule('old-schedule', 'paused')]))
        jest.mocked(hogFlowsSchedulesList).mockResolvedValue([schedule('old-schedule', 'paused')])
        jest.mocked(hogFlowsSchedulesCreate).mockResolvedValue(schedule('new-schedule', 'active'))

        await expectLogic(logic, () => logic.actions.launchBroadcast()).toFinishAllListeners()

        expect(hogFlowsSchedulesDestroy).toHaveBeenCalledWith(expect.any(String), 'broadcast-1', 'old-schedule')
        expect(hogFlowsSchedulesCreate).toHaveBeenCalledTimes(1)
        const activation = jest
            .mocked(hogFlowsPartialUpdate)
            .mock.calls.findIndex(([, , body]) => (body as any)?.status === 'active')
        expect(jest.mocked(hogFlowsSchedulesDestroy).mock.invocationCallOrder[0]).toBeLessThan(
            jest.mocked(hogFlowsPartialUpdate).mock.invocationCallOrder[activation]
        )
        expect(logic.values.broadcast?.schedules?.map((s) => s.id)).toEqual(['new-schedule'])
        expect(logic.values.canMoveToDraft).toBe(true)
    })

    it('moves a scheduled broadcast back to an editable draft', async () => {
        await mountWith(broadcastFixture('active', [schedule('s1', 'active')]))
        expect(logic.values.isReadOnly).toBe(true)

        await expectLogic(logic, () => logic.actions.moveToDraft()).toFinishAllListeners()

        expect(hogFlowsPartialUpdate).toHaveBeenCalledWith(expect.any(String), 'broadcast-1', { status: 'draft' })
        expect(logic.values.isReadOnly).toBe(false)
        expect(logic.values.scheduleMode).toBe('later')
    })

    it.each([
        ['a live broadcast waiting on its schedule', 'active', [schedule('s1', 'active')], [], true],
        ['a broadcast whose run is still sending', 'active', [schedule('s1', 'active')], ['active'], false],
        ['a broadcast whose schedule has finished', 'active', [schedule('s1', 'completed')], ['completed'], false],
        ['a broadcast sent right away with no schedule', 'active', [], ['completed'], false],
        ['a draft', 'draft', [schedule('s1', 'active')], [], false],
    ])('offers move to draft for %s: %s', async (_name, status, schedules, jobStatuses, expected) => {
        await mountWith(
            broadcastFixture(status, schedules),
            jobStatuses.map((jobStatus, index) => ({ id: `job-${index}`, status: jobStatus }) as HogFlowBatchJobApi)
        )

        expect(logic.values.canMoveToDraft).toBe(expected)
    })
})

