import { hogFlowsSchedulesDestroy, hogFlowsSchedulesList } from 'products/workflows/frontend/generated/api'
import type {
    HogFlowApi,
    HogFlowBatchJobApi,
    HogFlowScheduleApi,
} from 'products/workflows/frontend/generated/api.schemas'

import { canMoveBroadcastToDraft, deleteBroadcastSchedules } from './broadcastWizardLogic'

jest.mock('products/workflows/frontend/generated/api', () => ({
    ...jest.requireActual('products/workflows/frontend/generated/api'),
    hogFlowsSchedulesList: jest.fn(),
    hogFlowsSchedulesDestroy: jest.fn(),
}))

const schedule = (id: string, status: string): HogFlowScheduleApi => ({ id, status }) as unknown as HogFlowScheduleApi
const broadcast = (status: string, schedules: HogFlowScheduleApi[]): HogFlowApi =>
    ({ status, schedules }) as unknown as HogFlowApi
const job = { status: 'completed' } as HogFlowBatchJobApi

describe('broadcastWizardLogic', () => {
    it.each([
        ['a scheduled broadcast with no run', broadcast('active', [schedule('s1', 'active')]), [], true],
        ['a broadcast whose schedule was paused', broadcast('active', [schedule('s1', 'paused')]), [], true],
        ['a broadcast that already ran', broadcast('active', [schedule('s1', 'active')]), [job], false],
        ['a send-now broadcast with no schedule', broadcast('active', []), [], false],
        ['a draft', broadcast('draft', [schedule('s1', 'active')]), [], false],
        ['an archived broadcast', broadcast('archived', [schedule('s1', 'active')]), [], false],
    ])('moving %s to draft is allowed: %s', (_name, flow, batchJobs, expected) => {
        expect(canMoveBroadcastToDraft(flow, batchJobs)).toBe(expected)
    })

    it('deletes every existing schedule before a launch, including paused ones', async () => {
        jest.mocked(hogFlowsSchedulesList).mockResolvedValue([schedule('s1', 'paused'), schedule('s2', 'active')])
        jest.mocked(hogFlowsSchedulesDestroy).mockResolvedValue(undefined)

        await deleteBroadcastSchedules('1', 'flow-1')

        expect(jest.mocked(hogFlowsSchedulesDestroy).mock.calls).toEqual([
            ['1', 'flow-1', 's1'],
            ['1', 'flow-1', 's2'],
        ])
    })
})

